const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');

function jsonGet(path) {
  return new Promise((res, rej) => {
    http.get('http://localhost:9222' + path, r => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => res(JSON.parse(d)));
    }).on('error', rej);
  });
}

class CDP {
  constructor(url) {
    this.ws = new WebSocket(url);
    this.pending = new Map();
    this.nextId = 1;
    this.ws.on('message', msg => {
      const m = JSON.parse(msg.toString());
      if (m.id && this.pending.has(m.id)) { this.pending.get(m.id)(m); this.pending.delete(m.id); }
    });
  }
  send(method, params = {}) {
    return new Promise((res, rej) => {
      const id = this.nextId++;
      this.pending.set(id, res);
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => rej(new Error('timeout ' + method)), 10000);
    });
  }
  wait(ms) { return new Promise(r => setTimeout(r, ms)); }
}

(async () => {
  const targets = await jsonGet('/json');
  const page = targets.find(t => t.type === 'page' && t.url && t.url.includes('localhost:8080'));
  if (!page) { console.error('no page target', targets.map(t => t.url)); process.exit(1); }
  const cdp = new CDP(page.webSocketDebuggerUrl);
  await cdp.send('Page.enable');
  await cdp.wait(4500);
  const { data } = await cdp.send('Page.captureScreenshot', { format: 'jpeg', quality: 85 });
  fs.writeFileSync('/tmp/opencode/screen.jpg', Buffer.from(data, 'base64'));
  console.log('saved', fs.statSync('/tmp/opencode/screen.jpg').size, 'bytes');
  process.exit(0);
})().catch(e => { console.error(e); process.exit(1); });

