const WebSocket = require('ws');
const http = require('http');
function jsonGet(path) {
  return new Promise((res, rej) => {
    http.get('http://localhost:9222' + path, r => { let d=''; r.on('data',c=>d+=c); r.on('end',()=>res(JSON.parse(d))); }).on('error',rej);
  });
}
(async () => {
  const targets = await jsonGet('/json');
  const page = targets.find(t => t.type === 'page' && t.url && t.url.includes('localhost:8080'));
  const cdp = new WebSocket(page.webSocketDebuggerUrl);
  const pending = new Map(); let id = 0;
  cdp.on('open', async () => {
    await new Promise(r=>cdp.on('open',r)); // already open
    const send = (m,p={}) => new Promise((res,rej)=>{ const i=++id; pending.set(i,res); cdp.send(JSON.stringify({id,method:m,params:p})); setTimeout(()=>rej(new Error('timeout '+m)),5000); });
    cdp.on('message', msg => { const m=JSON.parse(msg.toString()); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
    cdp.on('message', msg => { const m=JSON.parse(msg.toString()); if (m.method === 'Runtime.consoleAPICalled') { console.log('CONSOLE', m.params.args.map(a=>a.value||a.description).join(' ')); } });
    await send('Runtime.enable');
    await send('Page.enable');
    await send('Page.reload');
    await new Promise(r=>setTimeout(r, 9000));
    const evs = await send('Log.get', {});
    console.log('LOGS', JSON.stringify(evs).slice(0, 1500));
    const dt = await send('Runtime.evaluate', { expression: 'document.pointerLockElement ? "locked" : "not locked"', returnByValue: true });
    console.log('LOCK STATE', JSON.stringify(dt.result.value));
    process.exit(0);
  });
})();

