    await send('Runtime.enable');
    await send('Page.enable');
    await send('Page.reload');
    await new Promise(r=>setTimeout(r, 14000));
    const key = (code, down) => send('Input.dispatchKeyEvent', { type: down ? 'keyDown' : 'keyUp', windowsVirtualKeyCode: code, nativeVirtualKeyCode: code, code: ''+code, key: ''+code });
    const press = async (code, holdMs) => { await key(code,true); await new Promise(r=>setTimeout(r,holdMs)); await key(code,false); };
    // move forward to make time flow, spawn enemies
    for (let i = 0; i < 80; i++) { await press(87, 30); await new Promise(r=>setTimeout(r,10)); } // W key = 87
    await new Promise(r=>setTimeout(r, 6000)); // let wave spawn enemies
    // shoot a few times (mouse down/up at center)
    const click = async () => { await send('Input.dispatchMouseEvent', { type:'mousePressed', x:640, y:360, button:'left', buttons:1, clickCount:1 }); await new Promise(r=>setTimeout(r,80)); await send('Input.dispatchMouseEvent', { type:'mouseReleased', x:640, y:360, button:'left', buttons:0, clickCount:1 }); };
    await click(); await new Promise(r=>setTimeout(r,250)); await click(); await new Promise(r=>setTimeout(r,250)); await click();
    await new Promise(r=>setTimeout(r, 3000)); // blood decals appear
    const kills = await send('Runtime.evaluate', { expression: 'document.querySelector("#kills").textContent', returnByValue: true });
    console.log('KILLS:', JSON.stringify(kills.result.value));
    const decals = await send('Runtime.evaluate', { expression: 'decals.length', returnByValue: true });
    console.log('DECALS:', JSON.stringify(decals.result.value));
    const {data} = await send('Page.captureScreenshot', { format: 'jpeg', quality: 82 });
    fs.writeFileSync('/tmp/opencode/gameplay.jpg', Buffer.from(data, 'base64'));
    console.log('GAMEPLAY SAVED', fs.statSync('/tmp/opencode/gameplay.jpg').size);
    process.exit(0);
  });
})();

